sys_script_include.script:
var DynamicExpectedValueHelper = Class.create();
DynamicExpectedValueHelper.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getExpectedValues: function() {
        var dictSysId = this.getParameter('sysparm_dict_sys_id');
        var result = {
            type: 'text',
            values: []
        };

        if (!dictSysId) {
            gs.error('[DynamicConfig] Missing sysparm_dict_sys_id parameter.');
            return JSON.stringify(result);
        }

        var dict = new GlideRecord('sys_dictionary');
        if (!dict.get(dictSysId)) {
            gs.error('[DynamicConfig] No dictionary entry found for sys_id: ' + dictSysId);
            return JSON.stringify(result);
        }

        var field = dict.getValue('element');
        var table = dict.getValue('name');
        var choice = dict.getValue('choice');
        var refTable = dict.getValue('reference');
        var internalType = dict.getValue('internal_type');

        gs.info('[DynamicConfig] Field: ' + field + ', Table: ' + table +
            ', Internal Type: ' + internalType + ', Choice: ' + choice +
            ', Reference: ' + refTable);

        // Case 1: Choice field
        if (choice == '1' || choice == '2' || internalType == 'choice') {
            result.type = 'choice';
            var choices = new GlideRecord('sys_choice');
            choices.addQuery('element', field);
            choices.addQuery('name', table);
            choices.addQuery('language', 'en');
            choices.orderBy('sequence');
            choices.query();
            while (choices.next()) {
                result.values.push({
                    value: choices.getValue('value'),
                    label: choices.getValue('label')
                });
            }
        }

        // Case 2: Reference field
        else if (internalType == 'reference') {
            result.type = 'reference';

            if (!refTable) {
                // Query the sys_dictionary table to get the reference table
                var dictGR = new GlideRecord('sys_dictionary');
                dictGR.addQuery('name', table); // Match the table name
                dictGR.addQuery('element', field); // Match the field name
                dictGR.query();

                if (dictGR.next()) {
                    refTable = dictGR.getValue('reference'); // Get the reference table
                }
            }

            if (refTable) {
                var refGr = new GlideRecord(refTable);
                if (refGr.isValid()) {
                    // Add query to filter active records (if applicable)
                    if (refTable == 'sys_user') {
                        refGr.addQuery('active', true); // Only fetch active users
                    }

					if (refTable == 'x_hsb11_hsbc_mss_o_business_process_stage'){

						refGr.addQuery('business_process','c0ccc3d21b079950ff37eb14b24bcb9f');
					}
                    // Order by the most recent records
                    refGr.orderByDesc('status');
                    refGr.setLimit(1500); // Limit to the most recent 500 records
                    refGr.query();

                    // Use an array to prevent duplicate display values
                    var seenLabels = []; // Array to track unique display labels
                    while (refGr.next()) {
                        var uniqueValue = refGr.getUniqueValue(); // sys_id or unique identifier
                        var displayValue = refGr.getDisplayValue(); // Fetch the display value directly

                        // Check if the display value (label) has already been added
                        if (seenLabels.indexOf(displayValue) === -1) {
                            result.values.push({
                                value: uniqueValue,
                                label: displayValue
                            });
                            seenLabels.push(displayValue); // Mark this display value as seen
                        }
                    }
                } else {
                    gs.error('[DynamicConfig] Invalid reference table: ' + refTable);
                }
            } else {
                gs.error('[DynamicConfig] Reference table not found for field: ' + field);
            }
        }

        // Case 3: Boolean field
        else if (internalType == 'boolean') {
            result.type = 'boolean';
            result.values = [
                { value: 'true', label: 'True' },
                { value: 'false', label: 'False' }
            ];
        }

        // Case 4: String field
        else if (internalType == 'string' || internalType == 'text') {
            result.type = 'string';
            result.values = []; // No predefined values for string fields
            gs.info('[DynamicConfig] String field detected: ' + field + ' in table: ' + table);
        }

        // Case 5: All other fields
        else {
            result.type = 'text';
            result.values = [];
            gs.info('[DynamicConfig] No specific handling for field type: ' + internalType);
        }

        return JSON.stringify(result);
    },

    type: 'DynamicExpectedValueHelper'
});
